void main() => runApp(const KatibaApp());

class KatibaApp extends StatelessWidget {
  const KatibaApp({super.key});
  @override Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false, title: 'Katiba VPN', locale: const Locale('ar'),
    theme: ThemeData(useMaterial3: true, fontFamily: 'sans', colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xff7c3aed), brightness: Brightness.dark), scaffoldBackgroundColor: const Color(0xff0b1020)),
    home: const SessionGate(),
  );
}

class SessionGate extends StatefulWidget { const SessionGate({super.key}); @override State<SessionGate> createState()=>_SessionGateState(); }
class _SessionGateState extends State<SessionGate> {
  final store = const FlutterSecureStorage(); final api = ApiService(); Map<String,String>? headers;
  @override void initState(){super.initState(); _load();}
  Future<void> _load() async { final raw=await store.read(key:'session_headers'); if(raw!=null){try{headers=Map<String,String>.from(jsonDecode(raw));}catch(_){}} if(mounted)setState((){}); }
  @override Widget build(BuildContext context)=>headers==null?LoginPage(api:api,onLogin:(h)async{await store.write(key:'session_headers',value:jsonEncode(h));setState(()=>headers=h);},):HomePage(api:api,headers:headers!,onLogout:()async{await store.delete(key:'session_headers');setState(()=>headers=null);});
}

class LoginPage extends StatefulWidget { final ApiService api; final Future<void> Function(Map<String,String>) onLogin; const LoginPage({super.key,required this.api,required this.onLogin}); @override State<LoginPage> createState()=>_LoginPageState(); }
class _LoginPageState extends State<LoginPage>{ final phone=TextEditingController(), code=TextEditingController(); Map<String,String>? otpHeaders; bool sent=false,busy=false; String? error; String normalize(String x){x=x.trim();if(x.startsWith('01'))return '2$x';if(x.startsWith('+2'))return x.substring(1);return x.replaceAll(RegExp(r'[ +]'),'');}
 Future<void> send()async{if(phone.text.trim().isEmpty)return;setState(()=>busy=true);try{otpHeaders=widget.api.baseHeaders();await widget.api.sendCode(normalize(phone.text),otpHeaders!);setState(()=>sent=true);}catch(e){setState(()=>error=e.toString());}finally{setState(()=>busy=false);}}
 Future<void> verify()async{if(otpHeaders==null)return;setState(()=>busy=true);try{final h=await widget.api.verify(normalize(phone.text),code.text.trim(),otpHeaders!);await widget.onLogin(h);}catch(e){setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}
 @override Widget build(BuildContext c)=>Scaffold(body: SafeArea(child: Center(child: SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:460),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.shield_rounded,size:82,color:Color(0xffa78bfa)),SizedBox(height:14),Text('KATIBA VPN',textAlign:TextAlign.center,style:TextStyle(fontSize:32,fontWeight:FontWeight.w900,letterSpacing:2)),SizedBox(height:8),Text('إدارة الرصيد والمهام والوحدات',textAlign:TextAlign.center,style:TextStyle(color:Colors.white60)),SizedBox(height:36),_Label('رقم الهاتف'),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:_dec('مثال: 010xxxxxxxx',Icons.phone_android)),if(sent)...[const SizedBox(height:16),_Label('رمز التحقق'),TextField(controller:code,keyboardType:TextInputType.number,decoration:_dec('أدخل الرمز المرسل',Icons.lock_outline))],if(error!=null)...[const SizedBox(height:14),Text(error!,textAlign:TextAlign.center,style:const TextStyle(color:Colors.redAccent))],const SizedBox(height:24),FilledButton.icon(onPressed:busy?null:(sent?verify:send),icon:busy?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2)):Icon(sent?Icons.login:Icons.sms),label:Text(busy?'جاري التنفيذ...':sent?'تسجيل الدخول':'إرسال رمز التحقق'),style:FilledButton.styleFrom(padding:const EdgeInsets.symmetric(vertical:16))),if(sent)TextButton(onPressed:busy?null:()=>setState(()=>sent=false),child:const Text('تغيير الرقم'))]))))));
}
InputDecoration _dec(String hint,IconData icon)=>InputDecoration(hintText:hint,prefixIcon:Icon(icon),filled:true,fillColor:Colors.white.withOpacity(.07),border:OutlineInputBorder(borderRadius:BorderRadius.circular(16),borderSide:BorderSide.none));
class _Label extends StatelessWidget{final String text;const _Label(this.text);@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.only(bottom:8),child:Text(text,style:const TextStyle(fontWeight:FontWeight.bold)));}

class HomePage extends StatefulWidget{final ApiService api;final Map<String,String> headers;final VoidCallback onLogout;const HomePage({super.key,required this.api,required this.headers,required this.onLogout});@override State<HomePage> createState()=>_HomePageState();}
class _HomePageState extends State<HomePage>{int tab=0;int balance=0;List<dynamic> history=[];List<PackageOption> options=[];bool loading=true;String status='';static const limit=2000;
 @override void initState(){super.initState();refresh();}
 Future<void> refresh()async{setState(()=>loading=true);try{balance=await widget.api.balance(widget.headers);history=await widget.api.history(widget.headers);final used=monthlyUnits(history);options=await widget.api.packages(widget.headers,balance,limit-used); }catch(e){status=e.toString();}finally{if(mounted)setState(()=>loading=false);}}
 int monthlyUnits(List<dynamic> rows){final now=DateTime.now();var total=0;for(final x in rows){if(x is! Map)continue;final ts=int.tryParse('${x['date']??0}')??0;if(ts==0)continue;final d=DateTime.fromMillisecondsSinceEpoch(ts);if(d.year!=now.year||d.month!=now.month||x['direction']!='DEBIT')continue;final s='${x['description']??''}';final m=RegExp(r'(\d+)\s*(?:وحدة|وحده|Units?|وحدات|EAND)',caseSensitive:false).firstMatch(s);if(m!=null)total+=int.parse(m.group(1)!);}return total;}
