 Future<void> redeem(PackageOption p)async{final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('تأكيد السحب'),content:Text('سحب ${p.units} وحدة مقابل ${p.cost} كوينز؟'),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('تأكيد'))]));if(ok!=true)return;setState(()=>loading=true);try{await widget.api.redeem(widget.headers,p);status='تم السحب بنجاح: ${p.units} وحدة';}catch(e){status=e.toString();}finally{await refresh();}}
 @override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:const Text('KATIBA VPN',style:TextStyle(fontWeight:FontWeight.w900)),actions:[IconButton(onPressed:refresh,icon:const Icon(Icons.refresh)),IconButton(onPressed:widget.onLogout,icon:const Icon(Icons.logout))]),body:loading?const Center(child:CircularProgressIndicator()):IndexedStack(index:tab,children:[dashboard(),missions(),historyPage(),redeemPage()]),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.dashboard_outlined),selectedIcon:Icon(Icons.dashboard),label:'الرئيسية'),NavigationDestination(icon:Icon(Icons.bolt_outlined),selectedIcon:Icon(Icons.bolt),label:'المهام'),NavigationDestination(icon:Icon(Icons.receipt_long_outlined),selectedIcon:Icon(Icons.receipt_long),label:'السجل'),NavigationDestination(icon:Icon(Icons.card_giftcard_outlined),selectedIcon:Icon(Icons.card_giftcard),label:'السحب')],)));
 Widget dashboard(){final used=monthlyUnits(history),remaining=(limit-used).clamp(0,limit),percent=used/limit;return ListView(padding:const EdgeInsets.all(18),children:[_hero(balance),const SizedBox(height:16),if(status.isNotEmpty)_status(status),Row(children:[Expanded(child:_metric('المستخدم هذا الشهر','$used','وحدة',Colors.orange)),const SizedBox(width:12),Expanded(child:_metric('المتبقي','$remaining','وحدة',Colors.green))]),const SizedBox(height:16),Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('تقدم الحد الشهري',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:12),LinearProgressIndicator(value:percent.clamp(0.0,1.0).toDouble(),minHeight:10,borderRadius:BorderRadius.circular(8),color:percent>.8?Colors.orange:Colors.green),const SizedBox(height:8),Text('${(percent*100).toStringAsFixed(1)}% من $limit وحدة')]))),const SizedBox(height:18),FilledButton.icon(onPressed:collect,icon:const Icon(Icons.bolt),label:const Text('جمع المهام المتاحة'),style:FilledButton.styleFrom(padding:const EdgeInsets.all(16))),]);}
 Widget _hero(int b)=>Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xff5b21b6),Color(0xff7c3aed)]),borderRadius:BorderRadius.circular(24)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('رصيدك الحالي',style:TextStyle(color:Colors.white70)),const SizedBox(height:8),Text('${NumberFormat('#,###').format(b)} كوينز',style:const TextStyle(fontSize:30,fontWeight:FontWeight.w900)),const SizedBox(height:12),Text(status.isEmpty?'كل بياناتك محدثة وآمنة':status,style:const TextStyle(color:Colors.white70))]));
 Widget _metric(String a,String b,String c,Color color)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.circle,color:color,size:14),const SizedBox(height:10),Text(a,style:const TextStyle(color:Colors.white60)),Text(b,style:TextStyle(fontSize:24,fontWeight:FontWeight.bold,color:color)),Text(c,style:const TextStyle(color:Colors.white60))])));
 Widget _status(String s)=>Padding(padding:const EdgeInsets.only(bottom:12),child:Card(color:Colors.deepPurple.withOpacity(.35),child:Padding(padding:const EdgeInsets.all(14),child:Text(s))));
 Widget missions()=>ListView(padding:const EdgeInsets.all(18),children:[_sectionTitle('جمع النقاط','تنفيذ المهام غير المكتملة'),FilledButton.icon(onPressed:collect,icon:const Icon(Icons.play_arrow),label:const Text('بدء جمع المهام')),if(status.isNotEmpty)Padding(padding:const EdgeInsets.only(top:16),child:_status(status))]);
 Widget historyPage()=>ListView(padding:const EdgeInsets.all(18),children:[_sectionTitle('سجل المعاملات','الوحدات المسحوبة خلال الشهر'),Card(child:Padding(padding:const EdgeInsets.all(16),child:Text('المسحوب هذا الشهر: ${monthlyUnits(history)} من $limit وحدة',style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold)))),const SizedBox(height:12),...history.take(30).map((x)=>Card(child:ListTile(leading:Icon(x['direction']=='DEBIT'?Icons.arrow_upward:Icons.arrow_downward,color:x['direction']=='DEBIT'?Colors.redAccent:Colors.green),title:Text('${x['description']??'معاملة'}'),subtitle:Text(x['date']==null?'':DateFormat('yyyy/MM/dd').format(DateTime.fromMillisecondsSinceEpoch(int.tryParse('${x['date']}')??0))),trailing:Text('${x['amount']??''}'))))]);
